function breakeven(fixed, price, variable){
  var cm=price-variable; if(cm<=0) return null;
  var q=fixed/cm;
  return {quantity:q, revenue:q*price, contributionMargin:cm, marginPct:cm/price};
}
function targetProfitUnits(fixed, price, variable, target){
  var cm=price-variable; if(cm<=0) return null;
  return (fixed+target)/cm;
}
var EXPORTS={breakeven:breakeven, targetProfitUnits:targetProfitUnits};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BreakevenForgePure = EXPORTS; }
